function CyberBackground() {
  const [streams, setStreams] = useState([])

  useEffect(() => {
    const spawn = () => {
      const id = Date.now()
      const type = Math.random() > 0.7 ? 'holo' : (Math.random() > 0.5 ? 'green' : 'blue')
      
      let text = ""
      if (type === 'green') {
        const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789*#@$!%/\\"
        text = Array(15).fill(0).map(() => chars[Math.floor(Math.random() * chars.length)]).join('')
      } else if (type === 'blue') {
        text = '0x' + Math.floor(Math.random() * 0xFFFFFFFF).toString(16).toUpperCase()
      } else {
        text = " [ HUD_SCAN_ACTIVE ] "
      }

      const newStream = {
        id,
        type,
        text,
        x: Math.random() * 100,
        y: Math.random() * 100,
        speed: type === 'holo' ? 2 + Math.random() * 3 : 5 + Math.random() * 10
      }
      setStreams(s => [...s.slice(-15), newStream])
    }
    const interval = setInterval(spawn, 1500)
    return () => clearInterval(interval)
  }, [])

  return (
    <div style={{ position: 'fixed', inset: 0, overflow: 'hidden', pointerEvents: 'none', zIndex: -1, opacity: 0.3 }}>
      <div className="scanlines" />
      <div className="grid-bg" />
      {streams.map(s => (
        <div key={s.id} style={{
          position: 'absolute',
          left: `${s.x}%`,
          top: `${s.y}%`,
          color: s.type === 'green' ? '#00ff88' : (s.type === 'blue' ? '#00aaff' : '#ffffff'),
          fontFamily: 'monospace',
          fontSize: s.type === 'holo' ? '1.2rem' : '0.7rem',
          fontWeight: s.type === 'holo' ? 'bold' : 'normal',
          textShadow: `0 0 8px ${s.type === 'green' ? '#00ff88' : (s.type === 'blue' ? '#00aaff' : '#fff')}`,
          whiteSpace: 'nowrap',
          animation: `flow-${s.type === 'holo' ? 'blue' : s.type} ${s.speed}s linear forwards`,
          border: s.type === 'holo' ? '1px solid rgba(255,255,255,0.3)' : 'none',
          padding: s.type === 'holo' ? '4px 10px' : '0',
          borderRadius: '4px'
        }}>
          {s.text}
        </div>
      ))}
      <style>{`
        @keyframes flow-green {
          0% { transform: translateY(-100%); opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { transform: translateY(100vh); opacity: 0; }
        }
        @keyframes flow-blue {
          0% { transform: translateX(100%); opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { transform: translateX(-100vw); opacity: 0; }
        }
        .grid-bg {
          position: absolute; inset: 0;
          background-image: linear-gradient(rgba(0, 255, 136, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(0, 255, 136, 0.05) 1px, transparent 1px);
          background-size: 50px 50px;
          z-index: 0;
        }
        .scanlines {
          position: absolute; inset: 0;
          background: linear-gradient(to bottom, transparent 50%, rgba(0, 255, 136, 0.02) 50%);
          background-size: 100% 4px;
          z-index: 1;
        }
      `}</style>
    </div>
  )
}

function CustomCursor() {
  const cursor = useRef(null)
  const [hovering, setHovering] = useState(false)

  useEffect(() => {
    const move = (e) => {
      if (cursor.current) {
        cursor.current.style.transform = `translate(${e.clientX}px, ${e.clientY}px)`
      }
    }
    const down = () => cursor.current && (cursor.current.style.transform += ' scale(0.85)')
    const up = () => cursor.current && (cursor.current.style.transform = cursor.current.style.transform.replace(' scale(0.85)', ''))
    const over = (e) => {
      const tag = e.target.tagName
      const isBtn = tag === 'BUTTON' || tag === 'A' || e.target.closest('button') || e.target.closest('a') || e.target.contentEditable === 'true'
      setHovering(!!isBtn)
    }
    window.addEventListener('mousemove', move)
    window.addEventListener('mousedown', down); window.addEventListener('mouseup', up)
    window.addEventListener('mouseover', over)
    return () => {
      window.removeEventListener('mousemove', move); window.removeEventListener('mousedown', down)
      window.removeEventListener('mouseup', up); window.removeEventListener('mouseover', over)
    }
  }, [])

  return (
    <>
      <div ref={cursor} style={{
        position: 'fixed', top: -2, left: -2,
        width: hovering ? 30 : 24, height: hovering ? 30 : 24,
        pointerEvents: 'none', zIndex: 99999,
        transition: 'width 0.2s, height 0.2s, transform 0.05s linear',
        filter: `drop-shadow(0 0 4px ${hovering ? '#00aaff' : '#00ff88'}) drop-shadow(0 0 10px ${hovering ? 'rgba(0,170,255,0.5)' : 'rgba(0,255,136,0.45)'})`,
      }}>
        <svg viewBox="0 0 24 24" width="100%" height="100%" aria-hidden="true">
          <path d="M3 2 L3 19 L8.5 14.5 L12 22 L15 20.5 L11.2 13 L19 13 Z"
            fill={hovering ? '#00aaff' : '#00ff88'} stroke="#0a0a0a" strokeWidth="1.2" strokeLinejoin="round" />
        </svg>
      </div>
      <style>{`
        body, button, a { cursor: none !important; }
        @media (max-width: 1024px) {
          body, button, a { cursor: auto !important; }
        }
      `}</style>
    </>
  )
}

